    "id": "revisao-rjal-gabinete-chefe",
    "law": "rjal",
    "topic": "Gabinetes de apoio",
    "subtopic": "Estatuto dos membros dos gabinetes de apoio pessoal",
    "familyId": "rjal:revisao-gabinete-chefe",
