    "id": "revisao-ccp-urgencia-imputavel",
    "law": "ccp",
    "topic": "Critérios materiais",
    "subtopic": "Escolha do ajuste direto para a formação de quaisquer contratos",
    "familyId": "ccp:revisao-urgencia-imputavel",
