    "id": "revisao-circ2-reporte-trimestre",
    "law": "circ2",
    "topic": "Registo de encargos na RAM",
    "subtopic": "Reporte trimestral da execução financeira",
    "familyId": "circ2:revisao-reporte-trimestre",
