    "id": "revisao-rgpd-rgpd-core-saude",
    "law": "rgpd",
    "topic": "Categorias especiais",
    "subtopic": "Tratamento de categorias especiais de dados pessoais",
    "familyId": "rgpd:revisao-rgpd-core-saude",
