    "id": "revisao-rgpd-rgpd-core-titular-cifrado",
    "law": "rgpd",
    "topic": "Violação de dados",
    "subtopic": "Comunicação de uma violação de dados pessoais ao titular dos dados",
    "familyId": "rgpd:revisao-rgpd-core-titular-cifrado",
