    "id": "revisao-rgpd-rgpd-epd-transfer-risco-residual",
    "law": "rgpd",
    "topic": "Avaliação e consulta prévia",
    "subtopic": "Consulta prévia",
    "familyId": "rgpd:revisao-rgpd-epd-transfer-risco-residual",
